"use client";

import { useState, useEffect } from "react";
import { useFinanceData, useSubmit } from "@/lib/api";
import { useRouter } from "next/navigation";
import { Card } from "@/components/finance/Card";
import { Skeleton } from "@/components/finance/Skeleton";
import { FormModal } from "@/components/finance/FormModal";
import { Button } from "@/components/finance/Button";
import { Input } from "@/components/finance/Input";
import { Slider } from "@/components/finance/Slider";
import { useReducedMotion } from "framer-motion";

const DebtPage = () => {
  const router = useRouter();
  const { data: debtData, isLoading, isError } = useFinanceData("/debt/overview");
  const { mutate: simulateDebt, data: simulateData, isLoading: isSimulating } = useSubmit("/api/finance/debt/simulate");
  const [extraPayment, setExtraPayment] = useState(0);
  const [salaryIncrease, setSalaryIncrease] = useState(0);
  const [bonus, setBonus] = useState(0);
  const [showModal, setShowModal] = useState(false);
  const isReducedMotion = useReducedMotion();

  useEffect(() => {
    if (isError) {
      alert("Failed to fetch debt data");
    }
  }, [isError]);

  const handleSimulate = () => {
    simulateDebt({ extra_payment: extraPayment, salary_increase: salaryIncrease, bonus: bonus });
  };

  if (isLoading) return <Skeleton />;

  if (!debtData || debtData.length === 0) return <Card title="Debt" content={<p>No debts found.</p>} />;

  return (
    <div className="flex flex-col gap-4">
      <Card title="Debt Overview">
        <div className="flex flex-col gap-2">
          {debtData.map((debt) => (
            <div key={debt.id} className="flex justify-between items-center">
              <p>{debt.name}</p>
              <p>{debt.outstanding}</p>
            </div>
          ))}
        </div>
      </Card>
      <Card title="Payoff Plan">
        <div className="flex flex-col gap-2">
          <p>Next EMI: {debtData[0].next_emi}</p>
          <p>Highest Interest: {debtData[0].highest_interest}</p>
        </div>
      </Card>
      <Card title="Simulate Debt Repayment">
        <div className="flex flex-col gap-2">
          <Input
            label="Extra Payment"
            type="number"
            value={extraPayment}
            onChange={(e) => setExtraPayment(Number(e.target.value))}
          />
          <Slider
            label="Salary Increase"
            min={0}
            max={10000}
            value={salaryIncrease}
            onChange={(value) => setSalaryIncrease(value)}
          />
          <Slider
            label="Bonus"
            min={0}
            max={5000}
            value={bonus}
            onChange={(value) => setBonus(value)}
          />
          <Button onClick={handleSimulate} disabled={isSimulating}>
            Simulate
          </Button>
          {simulateData && (
            <div>
              <p>Months Saved: {simulateData.months_saved}</p>
              <p>Interest Saved: {simulateData.interest_saved}</p>
            </div>
          )}
        </div>
      </Card>
      <Card title="Learning">
        <div className="flex flex-col gap-2">
          <p>Action: Create a detailed repayment plan for high-interest debt.</p>
          <p>Reason: Prioritize high-interest debt to avoid accumulating more interest.</p>
          <p>Learn: Use the debt simulator to explore different repayment strategies.</p>
        </div>
      </Card>
    </div>
  );
};

export default DebtPage;
